    try:
        if act['op'] == 'capture': o.capture()
        elif act['op'] == 'cancel': o.cancel()
        elif act['op'] == 'refund': o.refund(act['amount'])
        else: raise ValueError('bad op')
    except ValueError:
        failure = {'error':'ValueError','at_step':i}
        break
actual = failure if failure is not None else o.summary()
print('actual:', actual)
assert actual == artifact['expected'], (actual, artifact['expected'])
print('correct implementation matches expected')

# Simulate the canonical regression: remaining-balance check removed.
mutant = source.replace('        if amount > self.total_cents - self.refunded_cents:\n            raise ValueError("refund exceeds remaining balance")\n', '')
ns2 = {}
exec(mutant, ns2)
o2 = ns2['Order'](artifact['total_cents'])
failure2 = None
for i, act in enumerate(artifact['actions']):
    try:
        if act['op'] == 'capture': o2.capture()
        elif act['op'] == 'refund': o2.refund(act['amount'])
    except ValueError:
        failure2 = {'error':'ValueError','at_step':i}
        break
actual2 = failure2 if failure2 is not None else o2.summary()
print('missing-check mutant:', actual2)
print('regression exposed:', actual2 != artifact['expected'])
